const OWN = 'n8n.opc@gmail.com';
const TZ = 'Europe/Istanbul';
const PER_SENDER_DAY = 3;
const ALL_DAY = 100;
const AI_DAY = 200;
const BODY_MAX = 4000;
const ADDR = /[^\s<>,;"']+@[^\s<>,;"']+\.[^\s<>,;"']+/g;
const AUTOMATED = /^(mailer-daemon|postmaster|bounces?|no-?reply|do-?not-?reply|notifications?)([+.-].*)?@/i;
const addresses = (s) => (String(s || '').match(ADDR) || []).map((a) => a.toLowerCase());
const mask = (a) => {
  const at = a.lastIndexOf('@');
  const local = a.slice(0, at);
  const domain = a.slice(at + 1);
  const masked = local.length <= 1 ? local + '***' : local[0] + '***' + local[local.length - 1];
  return masked + '@' + domain;
};
const clean = (s, n) => {
  const t = String(s || '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const header = (p, name) => {
  const h = ((p && p.headers) || []).find((x) => String(x.name).toLowerCase() === name);
  return h ? h.value : '';
};
const b64 = (d) => Buffer.from(String(d).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
const walk = (part, acc) => {
  if (!part) return acc;
  const body = part.body || {};
  if (part.filename && body.attachmentId) acc.attachments += 1;
  else if (part.mimeType === 'text/plain' && body.data) acc.plain.push(b64(body.data));
  else if (part.mimeType === 'text/html' && body.data) acc.html.push(b64(body.data));
  (part.parts || []).forEach((c) => walk(c, acc));
  return acc;
};
const stripHtml = (h) => h
  .replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/p>|<\/div>|<\/li>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'").replace(/&quot;/g, '"');
const dropQuoted = (t) => {
  const cut = t.search(/\n\s*(On [^\n]{0,200}wrote:|-{2,}\s*Original Message|_{5,})/i);
  const s = cut > 0 ? t.slice(0, cut) : t;
  return s.split('\n').filter((l) => !/^\s*>/.test(l)).join('\n');
};
const state = $getWorkflowStaticData('global');
const today = DateTime.now().setZone(TZ).toISODate();
if (state.day !== today) { state.day = today; state.bySender = {}; state.total = 0; state.ai = 0; }
state.ai = state.ai || 0;
return $input.all().map((item, index) => {
  const m = item.json;
  const p = m.payload || {};
  const sender = addresses(header(p, 'from'))[0] || '';
  const to = addresses(header(p, 'to'));
  const subject = header(p, 'subject');
  const ms = Number(m.internalDate) || Date.now();
  const when = DateTime.fromMillis(ms).setZone(TZ);
  const parts = walk(p, { plain: [], html: [], attachments: 0 });
  const raw = parts.plain.length ? parts.plain.join('\n') : stripHtml(parts.html.join('\n'));
  const body = dropQuoted(raw).replace(/\r/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, BODY_MAX);
  const automated = !sender || sender === OWN || AUTOMATED.test(sender);
  const used = state.bySender[sender] || 0;
  const replyAllowed = !automated && used < PER_SENDER_DAY && state.total < ALL_DAY;
  if (replyAllowed) { state.bySender[sender] = used + 1; state.total += 1; }
  const analyzeAllowed = !automated && (body.length > 0 || subject.length > 0) && state.ai < AI_DAY;
  if (analyzeAllowed) state.ai += 1;
  return {
    json: {
      messageId: m.id,
      date: when.toFormat('yyyy-MM-dd'),
      time: when.toFormat('HH:mm'),
      receivedAt: when.toFormat("cccc, yyyy-MM-dd HH:mm"),
      fromMasked: sender ? mask(sender) : '(unknown)',
      toMasked: to.length ? to.map(mask).join(', ') : '(none)',
      about: clean(subject, 120) || clean(m.snippet, 120) || '(no subject)',
      hasAttachment: parts.attachments > 0 ? 'yes' : 'no',
      replyAllowed,
      analyzeAllowed,
      textForAi: 'Subject: ' + (subject || '(none)') + '\n\n' + (body || '(empty body)'),
    },
    pairedItem: { item: index },
  };
});

