{
  "type": "object",
  "properties": {
    "topic": { "type": "string", "description": "The main topic, idea or request of the email in one short English sentence, at most 15 words. No personal data." },
    "deadline_kind": { "type": "string", "enum": ["explicit", "implicit", "none"], "description": "explicit = a date or time is stated; implicit = implied by a relative phrase or context (by Friday, end of month, ASAP, before the meeting); none = no deadline." },
    "deadline_date": { "type": "string", "description": "The deadline as YYYY-MM-DD, resolved against the received date; empty string if none or not resolvable to a date." },
    "deadline_phrase": { "type": "string", "description": "The few words that set the deadline (at most 6 words, translated to English), or empty string." }
  },
  "required": ["topic", "deadline_kind", "deadline_date", "deadline_phrase"]
}

