const p = $('Parse and mask email').item.json;
const o = ($json && $json.output) || {};
const ADDR = /[^\s<>,;"']+@[^\s<>,;"']+\.[^\s<>,;"']+/g;
const mask = (a) => {
  const at = a.lastIndexOf('@');
  const local = a.slice(0, at);
  const masked = local.length <= 1 ? local + '***' : local[0] + '***' + local[local.length - 1];
  return masked + '@' + a.slice(at + 1);
};
const scrub = (s) => String(s || '')
  .replace(ADDR, (a) => mask(a.toLowerCase()))
  .replace(/https?:\/\/\S+|www\.\S+/gi, '[link]')
  .replace(/\+?\d[\d\s().-]{6,}\d/g, '[number]')
  .replace(/\s+/g, ' ')
  .trim();
const cap = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const topicRaw = cap(scrub(o.topic), 160);
const topic = topicRaw || (p.analyzeAllowed ? '(could not analyze)' : '(not analyzed)');
const kind = ['explicit', 'implicit'].includes(o.deadline_kind) ? o.deadline_kind : 'none';
const date = /^\d{4}-\d{2}-\d{2}$/.test(String(o.deadline_date || '')) ? o.deadline_date : '';
const phrase = cap(scrub(o.deadline_phrase), 40);
let deadline = '';
if (kind !== 'none' && date) deadline = kind === 'implicit' ? date + ' (implied' + (phrase ? ': ' + phrase : '') + ')' : date;
else if (kind !== 'none' && phrase) deadline = phrase;
return { json: {
  date: p.date,
  time: p.time,
  fromMasked: p.fromMasked,
  toMasked: p.toMasked,
  about: p.about,
  hasAttachment: p.hasAttachment,
  topic,
  deadline,
} };

const KEEP = 10;
const COLS = ['Date', 'Time', 'From', 'To', 'Subject', 'Attachment', 'Topic', 'Deadline'];
const fresh = $('Build sheet row').all().map((i) => ({
  Date: i.json.date, Time: i.json.time, From: i.json.fromMasked, To: i.json.toMasked,
  Subject: i.json.about, Attachment: i.json.hasAttachment, Topic: i.json.topic, Deadline: i.json.deadline,
}));
const old = $('Read current log').all()
  .map((i) => i.json)
  .filter((r) => r && r.Date)
  .map((r) => Object.fromEntries(COLS.map((c) => [c, r[c] === undefined || r[c] === null ? '' : String(r[c])])));
const key = (r) => String(r.Date) + ' ' + String(r.Time);
const rows = [...fresh.reverse(), ...old]
  .map((r, i) => ({ r, i }))
  .sort((a, b) => key(b.r).localeCompare(key(a.r)) || a.i - b.i)
  .slice(0, KEEP)
  .map(({ r }) => ({ json: r }));
return rows;
